import Foundation

/// 41 Atlas-taxonomy techniques. Verbatim port of web src/lib/techniques.ts (+ contrast, upfront-contract).
/// Each entry now carries the full Atlas record: id, name, cluster, mechanism,
/// verdict, folklore risk, canonical source, primary failure mode,
/// contraindication. Lessons detail view renders all of these.
public enum AtlasTechniques {
    public static let all: [Technique] = [
        // A · Compliance-gaining
        Technique(id: "fitd",     name: "Foot-in-the-door",     cluster: .compliance, mechanism: "Small initial compliance creates self-perception of being a compliant person; subsequent larger request is harder to refuse without identity inconsistency.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Cialdini 1984; Freedman & Fraser 1966", primaryFailureMode: "Reverse-causation: in commercial repeat-game contexts, the small ask can poison the target if perceived as transactional.", contraindication: "Single-shot consumer contexts where the target sees you only once; identity-relevance must hold.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "ditf",     name: "Door-in-the-face",     cluster: .compliance, mechanism: "Large initial request creates perception of concession when retreating to target; reciprocity norm activated.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984; O'Keefe & Hale 1998", primaryFailureMode: "Initial request implausible enough to insult; technique reads as manipulation.", contraindication: "Procurement specialists or persuasion-knowledge-high buyers.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "lowball",  name: "Low-ball",             cluster: .compliance, mechanism: "Initial small commitment binds participant; raised price after commitment is harder to refuse than same price offered initially.", atlasVerdict: .partiallyStudied, folkloreRisk: .mediumHigh, canonicalSource: "Cialdini et al. 1978", primaryFailureMode: "Catastrophic in repeat-game; experienced as deception at renewal.", contraindication: "Any repeat-game commercial context. The raised terms are experienced as bait-and-switch at renewal, and the trust collapse is the whole cost. Lab-real as a compliance effect, but its deal use is a deception that backfires the moment the true price surfaces.", evidenceTier: .a, evidenceBand: .flagged, evidenceSource: ""),
        Technique(id: "tna",      name: "That's-not-all",       cluster: .compliance, mechanism: "Sequential added bonuses before counter-offer activates reciprocity and value-anchoring.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Burger 1986", primaryFailureMode: "Density past buyer's perceived-fairness threshold reads as desperation.", contraindication: "Procurement; persuasion-knowledge-high buyers.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "disrupt-then-reframe", name: "Disrupt-then-reframe", cluster: .compliance, mechanism: "Unexpected pattern disruption creates micro-confusion; reframe in same breath bypasses critical evaluation.", atlasVerdict: .replicationFailed, folkloreRisk: .high, canonicalSource: "Davis & Knowles 1999 (replication concerns: Carpenter 2013)", primaryFailureMode: "Original cupcake-study replication failed. Brittle technique.", contraindication: "Any context where the reframe doesn't survive the buyer's later reflection.", evidenceTier: .a, evidenceBand: .flagged, evidenceSource: ""),

        // B · Cialdini six principles
        Technique(id: "reciprocity",   name: "Reciprocity",                 cluster: .cialdini, mechanism: "Norm of reciprocation creates obligation following unsolicited gift, favor, or concession.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Cialdini 1984; Regan 1971", primaryFailureMode: "Over-leveraged reciprocity degrades into transactional perception.", contraindication: "Frequent gifts to same buyer; transparent transactional framing.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "scarcity",      name: "Scarcity",                    cluster: .cialdini, mechanism: "Loss-aversion plus reactance: limited availability raises perceived value and urgency.", atlasVerdict: .partiallyStudied, folkloreRisk: .mediumHigh, canonicalSource: "Cialdini 1984", primaryFailureMode: "Manufactured scarcity detected = trust collapse plus reactance.", contraindication: "The meta-analytic support is for demand/supply scarcity ('almost sold out'), not the limited-time urgency reps manufacture. There is no B2B data, and manufactured urgency erodes perceived sincerity the moment a persuasion-aware buyer detects it. Backfires into reactance and distrust.", evidenceTier: .a, evidenceBand: .flagged, evidenceSource: ""),
        Technique(id: "authority",     name: "Authority cues",              cluster: .cialdini, mechanism: "Heuristic deference to expertise or status reduces deliberation cost.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984; Milgram", primaryFailureMode: "Titular authority without specific expertise triggers persuasion-knowledge.", contraindication: "Specificity-of-credential is the discriminator; never claim titular.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "social-proof",  name: "Social proof",                cluster: .cialdini, mechanism: "Uncertainty resolved by observing others' behavior; conformity heuristic activates.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Cialdini 1984; Deutsch & Gerard 1955", primaryFailureMode: "Generic social-proof ('thousands of customers') has low specificity-effect.", contraindication: "When peer set is dissimilar to buyer; named peers in same industry, role, stage carry weight.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "liking",        name: "Liking / similarity / rapport", cluster: .cialdini, mechanism: "Affect transfer from liked source to evaluated offer; similarity activates in-group cooperative heuristics.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984", primaryFailureMode: "Confusing warmth-of-interaction with accuracy-of-other-model.", contraindication: "Rapport predicts satisfaction and loyalty, not revenue; conversation-analytics finds top performers spend meaningfully LESS time on opening small-talk. Warm-up rapport treated as a revenue lever is unsupported and the small-talk-heavy open correlates with weaker close rates.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: "https://www.gong.io/win-rates"),
        Technique(id: "commitment-consistency", name: "Commitment & consistency", cluster: .cialdini, mechanism: "Prior public stance creates pressure to act consistently.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Cialdini 1984; SPIN (Rackham 1988)", primaryFailureMode: "Public plus written plus effortful commitments compound the effect; lone verbal weak.", contraindication: "When buyer feels trapped rather than guided.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),

        // C · Framing
        Technique(id: "loss-framing",    name: "Loss-aversion framing",       cluster: .framing, mechanism: "Asymmetric weighting of losses vs gains; status-quo bias activated.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Tversky & Kahneman 1981; Challenger Sale 2011", primaryFailureMode: "Over-deployed fear-frame triggers reactance.", contraindication: "Promotion-focused buyers (regulatory-fit mismatch).", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "contrast",        name: "Perceptual contrast",         cluster: .framing, mechanism: "A reference point set just before the target shifts how the target is judged — the same price reads as small after a larger anchor, large after a smaller one. Sequential, not absolute, evaluation.", atlasVerdict: .wellStudied, folkloreRisk: .lowMedium, canonicalSource: "Cialdini 1984 (contrast principle); Tversky & Kahneman 1974 (anchoring)", primaryFailureMode: "An implausible reference point reads as a manipulation rather than a comparison, and the contrast inverts into distrust.", contraindication: "Persuasion-knowledge-high buyers who recognize the staged comparison; unverifiable reference points.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "gain-framing",    name: "Gain framing",                cluster: .framing, mechanism: "Outcome-positive framing matches promotion-focus regulatory state.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Higgins 1997", primaryFailureMode: "Heterogeneous by buyer's regulatory focus; not universal.", contraindication: "Prevention-focused buyers.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "regulatory-fit",  name: "Regulatory fit",              cluster: .framing, mechanism: "Matching buyer's regulatory focus (prevention vs promotion) to message frame increases fluency and persuasion.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Higgins 1997, 1998", primaryFailureMode: "Misdiagnosis of buyer's regulatory focus produces frame inversion.", contraindication: "Requires accurate buyer-read first.", evidenceTier: .a, evidenceBand: .core, evidenceSource: "https://journals.sagepub.com/doi/abs/10.1509/jmkr.43.4.693"),
        Technique(id: "concrete-construal", name: "Concrete-vs-abstract framing", cluster: .framing, mechanism: "Psychologically-near framing matches near-construal of immediate decisions.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Trope & Liberman 2010; Voss 2016", primaryFailureMode: "Abstract framing at decision moment fails.", contraindication: "Early discovery where buyer needs abstract orientation.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),

        // D · Structural close
        Technique(id: "assumptive",         name: "Assumptive close",         cluster: .structuralClose, mechanism: "Default-option psychology; reframes decision from 'if' to 'which'.", atlasVerdict: .replicationFailed, folkloreRisk: .high, canonicalSource: "Hopkins 1980; Tracy 1995", primaryFailureMode: "Folklore-risk high. Felt-power inflates confidence in effect.", contraindication: "In complex or large sales the evidence points the OTHER way. Rackham's 35,000-call research found closing techniques REDUCE win rates with professional buyers; the assumptive close helps only in cheap, transactional, single-call sales and alienates a buying committee.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: "https://www.huthwaiteinternational.com/blog/complete-guide-to-spin-selling"),
        Technique(id: "alternative-choice", name: "Alternative-choice close", cluster: .structuralClose, mechanism: "Narrows decision space; default option reduces overwhelm.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Tracy", primaryFailureMode: "Folklore-risk high.", contraindication: "A softer forced-choice close carrying the same Rackham caveat: closing pressure suppresses win rates in large or complex sales and is tolerable only in transactional ones. Fails outright when the two options are not both favorable to the seller.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: "https://www.huthwaiteinternational.com/blog/complete-guide-to-spin-selling"),
        Technique(id: "summary-close",      name: "Summary close",            cluster: .structuralClose, mechanism: "Explicit summary of agreed value reduces decision uncertainty.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Hopkins; Rackham (SPIN); Dixon (Challenger)", primaryFailureMode: "Generic summary not mirroring buyer language.", contraindication: "When buyer hasn't yet articulated value criteria.", evidenceTier: .c, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "trial-close",        name: "Trial close",              cluster: .structuralClose, mechanism: "Elicits intermediate commitment; surfaces objections early.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Hopkins; SPIN", primaryFailureMode: "Premature trial close before discovery complete.", contraindication: "Before qualification is established.", evidenceTier: .d, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "takeaway",           name: "Takeaway close",           cluster: .structuralClose, mechanism: "Activates reactance and loss aversion; creates pursuit dynamic.", atlasVerdict: .untested, folkloreRisk: .mediumHigh, canonicalSource: "Voss 2016; Belfort", primaryFailureMode: "Read as bluff when BATNA lacks credibility.", contraindication: "A reactance/loss-aversion gambit with no B2B outcome data; reads as a bluff without a real BATNA and as manipulation to procurement specialists.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: ""),
        Technique(id: "ben-franklin",       name: "Ben Franklin close",       cluster: .structuralClose, mechanism: "Systematic enumeration favors seller's framing (more pros pre-loaded).", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Tracy", primaryFailureMode: "Folklore-risk high. Vibes-heavy.", contraindication: "Sophisticated B2B buyers; reads as theater.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: ""),
        Technique(id: "puppy-dog",          name: "Puppy-dog close",          cluster: .structuralClose, mechanism: "Endowment effect after possession.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Hopkins; SaaS industry; endowment literature (Kahneman 1991)", primaryFailureMode: "Free-trial without onboarding produces churn not endowment.", contraindication: "When trial friction is high enough to prevent endowment.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "sharp-angle",        name: "Sharp-angle close",        cluster: .structuralClose, mechanism: "Locks objection into commitment via conditional concession.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Belfort", primaryFailureMode: "Folklore-risk high. Ethics-flagged in repeat-game.", contraindication: "Carries the Rackham closing-technique caveat plus ethics exposure in any repeat-game deal; the conditional-concession lock reads as manipulation to a professional buyer and erodes trust.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: "https://www.huthwaiteinternational.com/blog/complete-guide-to-spin-selling"),

        // E · Question-form
        Technique(id: "calibrated-question", name: "Calibrated question",     cluster: .questionForm, mechanism: "Open-ended how/what stem invites buyer-generated elaboration; converts no-stance to problem-solving stance.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Voss 2016; Miller & Rollnick 2012; Rackham 1988", primaryFailureMode: "Regression to leading-question phrasing under live pressure.", contraindication: "When direct factual answer was required.", evidenceTier: .a, evidenceBand: .core, evidenceSource: "https://journals.sagepub.com/doi/abs/10.1509/jmkr.43.4.693"),
        Technique(id: "labeling",            name: "Affect labeling",         cluster: .questionForm, mechanism: "Verbalizing emotion reduces amygdala activation; signals empathy.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Voss 2016; Lieberman 2007", primaryFailureMode: "Scripted overuse triggers persuasion-knowledge.", contraindication: "The affect-labeling neuroscience (Lieberman 2007) regulates the SPEAKER'S OWN amygdala; no study shows that labeling a counterpart's emotion moves a deal. The mechanism is real but the sales outcome is unproven, and scripted labels trip persuasion-knowledge.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: "https://journals.sagepub.com/doi/10.1111/j.1467-9280.2007.01916.x"),
        Technique(id: "mirroring",           name: "Mirroring",               cluster: .questionForm, mechanism: "Last-3-words echo signals attention; minimal-encourager extends counterparty turn.", atlasVerdict: .partiallyStudied, folkloreRisk: .medium, canonicalSource: "Voss 2016", primaryFailureMode: "Echo-density triggers persuasion-knowledge.", contraindication: "Mimicry helps only when subtle and undetected and only in integrative negotiation; Maddux found no effect in distributive bargaining. Blatant or detected mirroring backfires, and Voss's specific last-3-words echo has never been tested for deal progression, so it is folklore as the named move.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: "https://www.sciencedirect.com/science/article/abs/pii/S0022103107000297"),
        Technique(id: "accusation-audit",    name: "Accusation audit",        cluster: .questionForm, mechanism: "Preemptively naming buyer's likely objections inoculates against them.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Voss 2016", primaryFailureMode: "Wrong-axis accusation surfaces objection buyer didn't have.", contraindication: "Wrong-axis pre-emption can plant an objection the buyer never held; name only the objections that are actually live.", evidenceTier: .c, evidenceBand: .supporting, evidenceSource: "https://www.gong.io/win-rates"),
        Technique(id: "spin-implication",    name: "SPIN implication question", cluster: .questionForm, mechanism: "Elicits buyer-generated cost of the problem; raises perceived problem severity.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Rackham 1988", primaryFailureMode: "Premature implication before problem is established.", contraindication: "Before buyer agrees a problem exists.", evidenceTier: .a, evidenceBand: .core, evidenceSource: "https://journals.sagepub.com/doi/abs/10.1509/jmkr.43.4.693"),
        Technique(id: "spin-need-payoff",    name: "SPIN need-payoff question", cluster: .questionForm, mechanism: "Elicits buyer-generated benefits; pre-commits buyer to solution rationale.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Rackham 1988", primaryFailureMode: "Asked before implication is felt; feels manipulative.", contraindication: "Before buyer feels the problem cost.", evidenceTier: .a, evidenceBand: .core, evidenceSource: "https://journals.sagepub.com/doi/abs/10.1509/jmkr.43.4.693"),

        // F · Negotiation-anchor
        Technique(id: "extreme-anchor",    name: "Extreme anchor",     cluster: .negotiationAnchor, mechanism: "Initial number anchors counterparty's adjustment.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Tversky & Kahneman 1974; Voss 2016; Galinsky", primaryFailureMode: "Anchor without BATNA produces walk-away.", contraindication: "Without credible BATNA.", evidenceTier: .a, evidenceBand: .core, evidenceSource: "https://www.gong.io/win-rates"),
        Technique(id: "precise-anchor",    name: "Precise number anchor", cluster: .negotiationAnchor, mechanism: "Precise numbers signal information; counterparty adjusts less.", atlasVerdict: .wellStudied, folkloreRisk: .low, canonicalSource: "Mason et al. 2013", primaryFailureMode: "Over-precision when buyer hasn't accepted negotiation frame.", contraindication: "Before pricing discussion is open.", evidenceTier: .a, evidenceBand: .core, evidenceSource: ""),
        Technique(id: "anchor-with-range", name: "Range anchor",       cluster: .negotiationAnchor, mechanism: "Range anchors with backed-bottom outperform point anchors.", atlasVerdict: .partiallyStudied, folkloreRisk: .lowMedium, canonicalSource: "Ames & Mason 2015", primaryFailureMode: "Range too wide signals uncertainty.", contraindication: "Adversarial counterparty.", evidenceTier: .a, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "bracketing",        name: "Bracketing",         cluster: .negotiationAnchor, mechanism: "Offers a range that brackets the target; counterparty meets in middle.", atlasVerdict: .untested, folkloreRisk: .medium, canonicalSource: "Voss 2016", primaryFailureMode: "Target visible to counterparty undermines effect.", contraindication: "When target inference is easy.", evidenceTier: .d, evidenceBand: .supporting, evidenceSource: ""),

        // G · Post-objection
        Technique(id: "feel-felt-found",     name: "Feel-felt-found",         cluster: .postObjection, mechanism: "Validates concern, then social-proof reframes.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Hopkins; Tracy", primaryFailureMode: "Scripted-cliche risk; pattern recognized immediately.", contraindication: "Scripted objection-rebuttal is the lowest evidence tier. The JOLT research (2.5M calls) shows stalls are won by proactive recommendation and taking risk off the table, not by rebuttal, and prevention via discovery beats any rebuttal one-liner. The cliche is pattern-recognized instantly.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: "https://www.jolteffect.com/blog/what-is-the-jolt-effect"),
        Technique(id: "isolate-and-conquer", name: "Isolate-the-objection",  cluster: .postObjection, mechanism: "Elicits commitment that this is the only objection; remove it and commitment follows.", atlasVerdict: .untested, folkloreRisk: .mediumHigh, canonicalSource: "Sandler; Belfort", primaryFailureMode: "Buyer hides true objection.", contraindication: "Buyers hide the true objection, and cornering them on 'is that the only thing?' can raise felt indecision; JOLT shows proactive recommendation, not isolation, resolves stalls.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: "https://www.jolteffect.com/blog/what-is-the-jolt-effect"),
        Technique(id: "reverse-objection",   name: "Boomerang / reverse objection", cluster: .postObjection, mechanism: "Reframes objection as a reason to buy.", atlasVerdict: .untested, folkloreRisk: .high, canonicalSource: "Tracy", primaryFailureMode: "Brittle. Reads as denial.", contraindication: "Reframing a genuine deal-blocker as a reason to buy reads as denial; prevention via discovery and proactive recommendation beat the boomerang.", evidenceTier: .d, evidenceBand: .flagged, evidenceSource: "https://www.jolteffect.com/blog/what-is-the-jolt-effect"),

        // H · Closing-environment
        Technique(id: "silence",          name: "Strategic silence after offer", cluster: .closingEnvironment, mechanism: "Discomfort-with-silence pushes counterparty to fill it (often with concession or commitment).", atlasVerdict: .untested, folkloreRisk: .medium, canonicalSource: "Sandler; Voss 2016", primaryFailureMode: "Broken too early.", contraindication: "Across cultural contexts where silence is comfortable.", evidenceTier: .d, evidenceBand: .supporting, evidenceSource: ""),
        Technique(id: "mutual-close-plan", name: "Mutual close plan (MAP)",      cluster: .closingEnvironment, mechanism: "Explicit shared timeline reduces stalls; multi-threading via named stakeholders.", atlasVerdict: .partiallyStudied, folkloreRisk: .low, canonicalSource: "MEDDIC; Force Management; commercial data (Gong/SBI)", primaryFailureMode: "MAP without exit-criteria becomes theater.", contraindication: "Tier-C correlational: mutual action plans and clear next steps track markedly higher close rates, but better reps also set them, so some of the lift is reverse causality. A MAP without real exit criteria becomes theater.", evidenceTier: .c, evidenceBand: .core, evidenceSource: "https://www.gong.io/win-rates"),
        Technique(id: "multi-threading",   name: "Multi-threading",              cluster: .closingEnvironment, mechanism: "Parallel relationships across stakeholders prevents single-point-of-failure on close.", atlasVerdict: .partiallyStudied, folkloreRisk: .low, canonicalSource: "Challenger Sale; MEDDIC; commercial data (CEB)", primaryFailureMode: "Multi-threading without champion installation = noise.", contraindication: "Tier-B analyst survey and Tier-C conversation-analytics converge, but both are correlational; higher-performing reps also multi-thread, so the effect size is inflated. Single-threaded deals are genuinely fragile.", evidenceTier: .b, evidenceBand: .core, evidenceSource: "https://www.gong.io/win-rates"),
        Technique(id: "upfront-contract", name: "Upfront Contract",       cluster: .closingEnvironment, mechanism: "Agree what the call is for — and what happens if it's not a fit — before you start it. The pre-agreed shape and named exit reduce defensiveness and convert a granted meeting into a decision.", atlasVerdict: .untested, folkloreRisk: .lowMedium, canonicalSource: "Sandler", primaryFailureMode: "Delivered as a script instead of an agreement; the buyer never actually consents and the contract becomes a monologue.", contraindication: "When the buyer has already set an explicit agenda; re-contracting over it reads as control.", evidenceTier: .d, evidenceBand: .supporting, evidenceSource: ""),
    ]

    private static let byId: [String: Technique] = Dictionary(uniqueKeysWithValues: all.map { ($0.id, $0) })

    public static func get(_ id: String) -> Technique? {
        byId[id]
    }

    public static func name(for id: String) -> String {
        byId[id]?.name ?? id
    }
}
